// Writes `dist/nrt/faust-env.js`: the module the NRT bundle imports Faust's C
// API from.
//
// An `extern "C"` block in Rust lands in a wasm import module literally named
// `env`, and wasm-bindgen passes it through untouched (`import * as import1
// from "env"`). A bare specifier needs an import map and a Worker gets none, so
// `build.sh` rewrites the specifier to point here and this file is generated
// from the bundle's **own declared imports** -- whatever the one JSON
// interpreter (`faust::boxes`, `faust::signals`) calls, and nothing else.
// Generated rather than written so the two cannot drift: an interpreter that
// grows a call the vendored compiler does not export fails at load, by name.
//
// The marshalling behind each one is `src/engine/faust-shim.js`.
import { readFileSync, writeFileSync } from "node:fs";

const bundle = "dist/nrt/clausters_nrt_web_bg.wasm";
const wasm = new WebAssembly.Module(readFileSync(bundle));
const names = WebAssembly.Module.imports(wasm)
    .filter((i) => i.module === "env")
    .map((i) => i.name)
    .sort();

const head = [
    "// Generated by clients/web/tools/gen-faust-env.mjs from the NRT bundle's",
    "// own imports: the Faust C API the one JSON interpreter calls.",
    'import { bind } from "./faust-shim.js";',
    "",
    "",
].join("\n");
const body = names.map((n) => `export const ${n} = bind(${JSON.stringify(n)});`).join("\n");
writeFileSync("dist/nrt/faust-env.js", head + body + "\n");
process.stderr.write(`faust-env.js: ${names.length} Faust imports bound\n`);
